  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params  // MUST await params
  return <h1>Blog Post: {slug}</h1>
}
```

### With Search Params (IMPORTANT: searchParams is now a Promise)
```tsx
// app/shop/page.tsx
