  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}) {
  const { page, sort } = await searchParams  // MUST await searchParams
  return <div>Page {page}, Sort: {sort}</div>
}
```

### Page Props Helper (Global Type Helper)
```tsx
// Provides strong typing from route literal
export default async function Page(props: PageProps<'/blog/[slug]'>) {
  const { slug } = await props.params
  const query = await props.searchParams
  return <h1>Blog Post: {slug}</h1>
}
```

**Important Notes:**
- Pages are **Server Components by default**
- `params` and `searchParams` are **Promises** (changed in v15)
- Use `async/await` or React's `use()` function
- A page file is required to make a route publicly accessible
- Pages are always the **leaf** of the route tree

