- **NO `getStaticProps`** - Just make async Server Components
- **NO `getStaticPaths`** - Use `generateStaticParams` instead
- Fetch responses are NOT cached by default (use `{ cache: 'force-cache' }` to opt in)
- Use `React.cache()` for non-fetch requests (ORMs, file system)

## 7. Dynamic Routes

### Single Dynamic Segment
```tsx
// app/blog/[slug]/page.tsx
export default async function Page({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  return <h1>Post: {slug}</h1>
}
```

### Catch-All Segments
```tsx
// app/shop/[...slug]/page.tsx
// Matches: /shop/a, /shop/a/b, /shop/a/b/c
export default async function Page({
  params,
}: {
  params: Promise<{ slug: string[] }>
}) {
  const { slug } = await params
  return <div>Path: {slug.join('/')}</div>
}
```

### Optional Catch-All
```tsx
// app/shop/[[...slug]]/page.tsx
// Matches: /shop, /shop/a, /shop/a/b
export default async function Page({
  params,
}: {
  params: Promise<{ slug?: string[] }>
}) {
  const { slug } = await params
  return <div>Path: {slug?.join('/') || 'root'}</div>
}
```

### generateStaticParams (Replaces getStaticPaths)
```tsx
// app/blog/[slug]/page.tsx
export async function generateStaticParams() {
  const posts = await fetch('https://api.example.com/posts')
    .then(res => res.json())

  return posts.map((post: Post) => ({
    slug: post.slug,
  }))
}

export default async function Page({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  // Render page
}
```

**URL to params mapping:**
| Route | URL | params |
|-------|-----|--------|
| `app/shop/[slug]/page.js` | `/shop/1` | `{ slug: '1' }` |
| `app/shop/[...slug]/page.js` | `/shop/1/2` | `{ slug: ['1', '2'] }` |
| `app/shop/[[...slug]]/page.js` | `/shop` | `{ slug: undefined }` |

## 8. Not-Found Pages

### Route-Level Not Found
```tsx
// app/blog/[slug]/page.tsx
import { notFound } from 'next/navigation'

export default async function Page({ params }) {
  const { slug } = await params
  const post = await getPost(slug)

  if (!post) {
    notFound()  // Triggers not-found.tsx
  }

  return <div>{post.title}</div>
}

// app/blog/[slug]/not-found.tsx
export default function NotFound() {
  return (
    <div>
      <h2>Post Not Found</h2>
      <Link href="/blog">View all posts</Link>
    </div>
  )
}
```

### Global Not Found (Experimental)
```tsx
// next.config.ts
const config = {
  experimental: {
    globalNotFound: true,
  },
}

// app/global-not-found.tsx
import './globals.css'

export const metadata = {
  title: '404 - Page Not Found',
}

export default function GlobalNotFound() {
  return (
    <html lang="en">
      <body>
        <h1>404 - Page Not Found</h1>
      </body>
    </html>
  )
}
```

**Important:**
- `not-found.js` returns 200 for streamed, 404 for non-streamed
- `global-not-found.js` must include `<html>` and `<body>`
- Root `app/not-found.js` handles all unmatched URLs

## 9. Error Handling

### Error Boundaries (error.tsx)
```tsx
// app/dashboard/error.tsx
'use client'  // Error boundaries MUST be Client Components

import { useEffect } from 'react'

export default function ErrorPage({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div>
      <h2>Something went wrong!</h2>
      <button onClick={() => reset()}>Try again</button>
    </div>
  )
}
```

### Global Error
```tsx
// app/global-error.tsx
'use client'

export default function GlobalError({ error, reset }) {
  return (
    <html>
      <body>
        <h2>Something went wrong!</h2>
        <button onClick={() => reset()}>Try again</button>
      </body>
    </html>
  )
}
```

### Expected Errors (Server Actions)
```tsx
// app/actions.ts
'use server'

export async function createPost(prevState: any, formData: FormData) {
  const res = await fetch('https://api.example.com/posts', {
    method: 'POST',
    body: formData,
  })

  if (!res.ok) {
    return { message: 'Failed to create post' }  // Return error
  }
}

// app/ui/form.tsx
'use client'
import { useActionState } from 'react'

export function Form() {
  const [state, formAction] = useActionState(createPost, { message: '' })

  return (
    <form action={formAction}>
      {state?.message && <p>{state.message}</p>}
      <button>Submit</button>
    </form>
  )
}
```

**Error Types:**
- **Expected errors** - Model as return values, not thrown
- **Uncaught exceptions** - Throw errors, caught by error boundaries
- Error boundaries catch rendering errors, NOT event handlers

## 10. Client Components ('use client' directive)

### When to Use Client Components
Use when you need:
- State (`useState`, `useReducer`)
- Event handlers (`onClick`, `onChange`)
- Lifecycle effects (`useEffect`)
- Browser APIs (`window`, `localStorage`, `navigator`)
- Custom hooks
- React Context

### Basic Client Component
```tsx
// app/ui/counter.tsx
'use client'

import { useState } from 'react'

export default function Counter() {
  const [count, setCount] = useState(0)

  return (
    <div>
      <p>{count} likes</p>
      <button onClick={() => setCount(count + 1)}>Click me</button>
    </div>
  )
}
```

### Composing Server and Client
```tsx
// app/page.tsx (Server Component)
import Modal from './ui/modal'
import Cart from './ui/cart'

export default function Page() {
  return (
    <Modal>
      <Cart />  {/* Server Component inside Client Component */}
    </Modal>
  )
}

// app/ui/modal.tsx (Client Component)
'use client'

export default function Modal({ children }: { children: React.ReactNode }) {
  return <div>{children}</div>
}
```

### Context Providers
```tsx
// app/theme-provider.tsx
'use client'

import { createContext } from 'react'

export const ThemeContext = createContext({})

export default function ThemeProvider({ children }) {
  return (
    <ThemeContext.Provider value="dark">
      {children}
    </ThemeContext.Provider>
  )
}

// app/layout.tsx (Server Component)
import ThemeProvider from './theme-provider'

export default function RootLayout({ children }) {
  return (
    <html>
      <body>
        <ThemeProvider>{children}</ThemeProvider>
      </body>
    </html>
  )
}
```

### Wrapping Third-Party Components
```tsx
// app/carousel.tsx
'use client'

import { Carousel } from 'acme-carousel'

export default Carousel  // Now usable in Server Components
```

**Key Principles:**
- All components are **Server Components by default**
- `'use client'` creates a boundary - all imports/children are client bundle
- Minimize client bundle size - only mark interactive parts as client
- Pass Server Components as `children` to Client Components
- Can pass data from Server to Client via props (must be serializable)

### Preventing Environment Poisoning
```ts
// lib/data.ts
import 'server-only'  // Throws error if imported in client

export async function getData() {
  const res = await fetch('https://api.example.com', {
    headers: {
      authorization: process.env.API_KEY,  // Server-only secret
    },
  })
  return res.json()
}
```

---

## Key Migration Takeaways

1. **No more data fetching functions** - Just async Server Components
2. **params and searchParams are Promises** - Must await them
3. **Layouts don't re-render** - Can't access searchParams or pathname
4. **Client Components need 'use client'** - Server by default
5. **Route Handlers replace API Routes** - Use `route.ts` not `pages/api`
6. **Metadata API** - No manual `<Head>` manipulation
7. **Error boundaries must be Client Components** - Use `error.tsx`
8. **Streaming with Suspense** - Use `loading.tsx` or `<Suspense>`
9. **generateStaticParams replaces getStaticPaths**
10. **File-system based routing** - Folders = routes, files = UI

This is a fundamentally different model from Pages Router. Take time to understand Server vs Client Components, as this is the core paradigm shift.

